// Pseudo-C-like snippet illustrating the bump allocator
void* allocate(size_t sz){
  size_t a = (offset + 7) & ~7ULL; // align to 8
  if (a + sz > ARENA_SIZE) return NULL;
  void* p = (char*)arena + a;
  offset = a + sz;
  return p;
}
```

